function(params) {
  try {
    if (typeof game === 'undefined' || !game) return { error: true, message: '控制桥未就绪' };
    if (typeof game.getPlayers !== 'function' || typeof game.setInvincible !== 'function') return { error: true, message: '沙箱未开放所需方法' };
    var players = game.getPlayers();
    if (!players.length) return { error: true, message: '暂无玩家' };
    var p = players[0];
    var dur = (params && params.duration) ? params.duration : 15;
    game.setInvincible(p, true);
    if (typeof setTimeout === 'function') {
      setTimeout(function() { game.setInvincible(p, false); }, dur * 1000);
    }
    return { message: '🛡️ 定向无敌 ' + dur + ' 秒（仅使用者）' };
  } catch (e) {
    return { error: true, message: '定向无敌异常: ' + (e && e.message ? e.message : e) };
  }
}
